gMT(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u0441 \u0442\u0430\u043a\u0438\u043c \u043a\u043e\u0434\u043e\u043c \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d"},
gux(){return"\u041d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442 \u0438 \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437."},
gNu(){return"\u041d\u0430\u0447\u0430\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u043f\u043e\u0445\u043e\u0434?"},
gNt(){return"\u041a\u0443\u043f\u043b\u0435\u043d\u043d\u043e\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u044e \u043f\u043e\u043a\u0443\u043f\u043e\u043a, \u0432\u0441\u0435 \u043e\u0442\u043c\u0435\u0442\u043a\u0438 \u0431\u0443\u0434\u0443\u0442 \u0441\u043d\u044f\u0442\u044b \u2014 \u0441\u043f\u0438\u0441\u043e\u043a \u0441\u0442\u0430\u043d\u0435\u0442 \u0447\u0438\u0441\u0442\u044b\u043c. \u0421\u0430\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u044b \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f."},
gcU(){return"\u041d\u0430\u0447\u0430\u0442\u044c"},
gGJ(){return"\u041a \u043f\u043e\u043a\u0443\u043f\u043a\u0435 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u043e.\n\u041e\u0442\u043c\u0435\u0442\u044c\u0442\u0435 \u0442\u043e\u0432\u0430\u0440\u044b \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 \u043f\u0435\u0440\u0435\u0434 \u043f\u043e\u0445\u043e\u0434\u043e\u043c."},
