Kv(a,b){return a+": \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043e "+b+" \u0442\u043e\u0432\u0430\u0440\u043e\u0432"},
gKu(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043a\u0430\u0442\u0430\u043b\u043e\u0433. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442."},
gEW(){return"\u0426\u0435\u043d\u0430, \u20ac"},
Pa(a,b){return"\u041a \u043f\u043e\u043a\u0443\u043f\u043a\u0435: "+a+" \xb7 \u2248"+b+" \u20ac"},
gGM(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430: \u044d\u043a\u0440\u0430\u043d \u043d\u0435 \u043f\u043e\u0433\u0430\u0441\u043d\u0435\u0442"},
gGL(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d"},
MP(a){return"\xab"+a+"\xbb \u0443\u0434\u0430\u043b\u0451\u043d"},
gtY(){return"\u041e\u0442\u043c\u0435\u043d\u0438\u0442\u044c"},
