gKz(){return"\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0438"},
gLq(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u0441\u043f\u0438\u0441\u043e\u043a?"},
Lp(a){return"\xab"+a+"\xbb \u0438 \u0432\u0441\u0435 \u0435\u0433\u043e \u0442\u043e\u0432\u0430\u0440\u044b \u0431\u0443\u0434\u0443\u0442 \u0443\u0434\u0430\u043b\u0435\u043d\u044b."},
