gMV(){return"\u0412\u044b \u0432 \u043e\u0431\u0449\u0435\u043c \u0441\u043f\u0438\u0441\u043a\u0435"},
MJ(a){return"\u0415\u0441\u043b\u0438 \u0428\u043e\u043f\u043b\u0438\u0441\u0442 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u043d\u0430 \u044d\u043a\u0440\u0430\u043d \xab\u0414\u043e\u043c\u043e\u0439\xbb, \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0433\u043e \u0438 \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u043a\u043e\u0434 \u0442\u0430\u043c: \u043c\u0435\u043d\u044e \u22ef \u2192 \xab\u041f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u044c\u0441\u044f \u043f\u043e \u043a\u043e\u0434\u0443\xbb \u2192 "+a+".\n\nSafari \u0438 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0445\u0440\u0430\u043d\u044f\u0442 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u2014 \u0431\u0435\u0437 \u044d\u0442\u043e\u0433\u043e \u0448\u0430\u0433\u0430 \u0441\u043f\u0438\u0441\u043e\u043a \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0434\u0435\u0441\u044c, \u0432 Safari."},
Lr(a,b){return"\u0421\u043f\u0438\u0441\u043e\u043a \u043e\u0431\u0449\u0438\u0439: \xab"+a+"\xbb \u0438 \u0432\u0441\u0435 \u0435\u0433\u043e \u0442\u043e\u0432\u0430\u0440\u044b \u0438\u0441\u0447\u0435\u0437\u043d\u0443\u0442 \u0443 \u0412\u0421\u0415\u0425 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 ("+b+"), \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0443 \u0432\u0430\u0441."},
gGs(){return"\u0412\u044b\u0439\u0442\u0438"},
Ke(a){return"\u0421\u0441\u044b\u043b\u043a\u0430 \u0434\u043b\u044f \u0432\u0445\u043e\u0434\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430 \u043d\u0430 "+a+". \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u043d\u0430 \u044d\u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u2014 \u0432\u0445\u043e\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438."},
gE4(){return"\u041a\u0430\u043a \u044d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442"},
gO1(){return"\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c"},
